import { readFile } from "node:fs/promises";
import * as clientModule from "./extensions/system-one/client.ts";
import { readSystemOneConfig } from "./extensions/system-one/config.ts";

const source = await readFile("./extensions/system-one/client.ts", "utf8");
if (/fetch\s*\(/.test(source)) {
  console.error("system-one client still calls fetch directly");
  process.exit(1);
}

const model = { id: "jev-latest" };
const registry = {
  getModelOfType(type, provider, modelId) {
    if (type !== "classifier") return undefined;
    return modelId === "jev-latest" ? model : undefined;
  },
  findOfType(type, provider, modelId) {
    return this.getModelOfType(type, provider, modelId);
  },
  async classify(_model, context) {
    if (!context.state || typeof context.state !== "object" || Array.isArray(context.state)) {
      console.error("state was not wrapped as a JSON object:", context.state);
      process.exit(1);
    }
    if (context.questions.q?.type !== "choice") {
      console.error("choice question was not mapped");
      process.exit(1);
    }
    return {
      stopReason: "stop",
      answers: { q: { type: "choice", choice: "fix", confidence: 0.9 } },
    };
  },
};

const base = readSystemOneConfig({ TYPESAFE_API_KEY: "k" });
const config = { provider: "typesafe", ...base, model: "jev-latest" };
const factories = [
  clientModule.createRegistrySystemOneClient,
  clientModule.createClassifierSystemOneClient,
  clientModule.createSystemOneClient,
].filter((factory) => typeof factory === "function");

let client;
for (const factory of factories) {
  for (const args of [[registry, config], [config, registry]]) {
    try {
      const candidate = factory(...args);
      if (candidate && typeof candidate.decide === "function") {
        client = candidate;
        break;
      }
    } catch {
      // Try the other argument order or factory.
    }
  }
  if (client) break;
}
if (!client) {
  console.error("no registry-based client factory was found");
  process.exit(1);
}

const result = await client.decide({
  question: { id: "q", instructions: "classify", criteria: { fix: "fix", review: "review" } },
  state: "x",
});
if (result?.choice !== "fix" || result.confidence !== 0.9) {
  console.error("registry decision was not parsed", result);
  process.exit(1);
}
EOF

