import planMode from "./extensions/plan-mode/index.ts";

const handlers = new Map();
const commands = new Map();
const appended = [];
let active = ["read", "edit", "write", "sandbox_authorize_read"];

const pi = {
  registerFlag() {},
  registerCommand(name, definition) { commands.set(name, definition.handler); },
  registerShortcut() {},
  appendEntry(customType, data) { appended.push({ type: "custom", customType, data }); },
  on(name, handler) {
    if (!handlers.has(name)) handlers.set(name, []);
    handlers.get(name).push(handler);
  },
  getFlag() { return false; },
  getActiveTools() { return [...active]; },
  setActiveTools(names) { active = [...names]; },
};
const ctx = {
  hasUI: true,
  sessionManager: { getEntries() { return []; } },
  ui: {
    notify() {},
    setStatus() {},
    setWidget() {},
    theme: { fg(_color, text) { return text; } },
  },
};
planMode(pi);

await commands.get("plan")("", ctx);
if (active.includes("edit") || active.includes("write")) {
  console.error("write tools remain active in plan mode:", active);
  process.exit(1);
}
if (!active.includes("sandbox_authorize_read")) {
  console.error("plan mode dropped a non-write tool:", active);
  process.exit(1);
}

active.push("tool-activated-during-plan");
await commands.get("plan")("", ctx);
if (!active.includes("tool-activated-during-plan") || !active.includes("edit")) {
  console.error("exit lost tools:", active);
  process.exit(1);
