import { mkdtemp, mkdir, writeFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import externalMemoryExtension from "./extensions/external-memory/index.ts";

const root = await mkdtemp(join(tmpdir(), "pilot-memory-root-"));
const cwd = await mkdtemp(join(tmpdir(), "pilot-memory-project-"));
const previous = process.env.PI_AGENT_MEMORY_ROOT;
process.env.PI_AGENT_MEMORY_ROOT = root;

try {
  await mkdir(join(cwd, ".pi"), { recursive: true });
  await writeFile(
    join(cwd, ".pi", "external-memory.json"),
    JSON.stringify({ enabled: true, projectId: "pilot" }),
  );

  const handlers = new Map();
  const commands = new Map();
  const tools = [];
  let active = [];
  const pi = {
    on(name, handler) { handlers.set(name, handler); },
    registerCommand(name, definition) { commands.set(name, definition.handler); },
    registerTool(tool) {
      tools.push(tool);
      if (tool.defaultActive !== false) active.push(tool.name);
    },
    getActiveTools() { return [...active]; },
    setActiveTools(names) { active = [...names]; },
  };
  const ctx = {
    cwd,
    mode: "tui",
    hasUI: true,
    sessionManager: {
      getEntries() { return []; },
      getSessionId() { return "s1"; },
      getLeafId() { return "b1"; },
    },
    ui: {
      notify() {},
      async confirm() { return true; },
    },
  };

  externalMemoryExtension(pi);
  await handlers.get("session_start")({}, ctx);
  if (!tools.some((tool) => tool.name === "memory_recall")) {
    console.error("memory_recall was not registered");
    process.exit(1);
  }
  if (!active.includes("memory_recall")) {
    console.error("memory_recall was not active after opt-in");
    process.exit(1);
  }

  await commands.get("memory")("off", ctx);
  if (active.includes("memory_recall")) {
    console.error("memory_recall stayed active after /memory off");
    process.exit(1);
  }
} finally {
  if (previous === undefined) delete process.env.PI_AGENT_MEMORY_ROOT;
  else process.env.PI_AGENT_MEMORY_ROOT = previous;
  await rm(root, { recursive: true, force: true });
  await rm(cwd, { recursive: true, force: true });
}
EOF
